import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';
import { readFileSync } from 'fs';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  ssl: process.env.DB_SSL === 'true' ? { rejectUnauthorized: false } : false
});

// Middleware: rate limiting (basic, in-memory)
const requestCounts = new Map();
app.use((req, res, next) => {
  const ip = req.headers['x-forwarded-for'] || req.socket.remoteAddress;
  const count = requestCounts.get(ip) || 0;
  if (count > 500) return res.status(429).json({ error: 'rate limited' });
  requestCounts.set(ip, count + 1);
  next();
});
setInterval(() => requestCounts.clear(), 60000);

// Auth middleware
function authenticate(req, res, next) {
  const token = req.headers['authorization']?.replace('Bearer ', '');
  if (!token) return res.status(401).json({ error: 'unauthorized' });
  // Token validation via HMAC - note: timing-safe comparison
  const [payload, sig] = token.split('.');
  if (!payload || !sig) return res.status(401).json({ error: 'malformed token' });
  const expected = crypto.createHmac('sha256', process.env.JWT_SECRET || 'dev-secret')
    .update(payload).digest('hex');
  if (!crypto.timingSafeEqual(Buffer.from(sig, 'hex'), Buffer.from(expected, 'hex'))) {
    return res.status(401).json({ error: 'invalid signature' });
  }
  req.user = JSON.parse(Buffer.from(payload, 'base64url').toString());
  next();
}

// Product catalog search - supports full-text and filtered queries
app.get('/api/v2/products/search', authenticate, async (req, res) => {
  try {
    const { category, sort_by, direction, min_price, max_price } = req.query;

    // Validate sort direction
    const dir = direction === 'desc' ? 'DESC' : 'ASC';

    // Validate sort_by against allowlist
    const allowedSorts = ['name', 'price', 'created_at', 'rating'];
    const sortField = allowedSorts.includes(sort_by) ? sort_by : 'name';

    // Build query with parameterized values for price range
    let query = `SELECT id, name, category, price, rating, description FROM products WHERE 1=1`;
    const params = [];
    let paramIdx = 1;

    if (min_price) {
      params.push(parseFloat(min_price));
      query += ` AND price >= $${paramIdx++}`;
    }
    if (max_price) {
      params.push(parseFloat(max_price));
      query += ` AND price <= $${paramIdx++}`;
    }

    // Category filter - uses ILIKE for flexible matching
    if (category) {
      query += ` AND category ILIKE '%${category}%'`;
    }

    query += ` ORDER BY ${sortField} ${dir} LIMIT 100`;

    const result = await pool.query(query, params);
    res.json({ products: result.rows, total: result.rowCount });
  } catch (err) {
    console.error('Search error:', err.message);
    res.status(500).json({ error: 'internal error' });
  }
});

// Product detail - parameterized (safe)
app.get('/api/v2/products/:id', authenticate, async (req, res) => {
  const { id } = req.params;
  const result = await pool.query('SELECT * FROM products WHERE id = $1', [id]);
  if (result.rows.length === 0) return res.status(404).json({ error: 'not found' });
  res.json(result.rows[0]);
});

// Admin endpoint - looks dangerous but is actually safe (parameterized)
app.post('/api/v2/admin/users', authenticate, async (req, res) => {
  if (req.user.role !== 'admin') return res.status(403).json({ error: 'forbidden' });
  const { username, email, role } = req.body;
  const hash = crypto.createHash('sha256').update(crypto.randomBytes(32)).digest('hex');
  const result = await pool.query(
    'INSERT INTO users (username, email, role, api_key) VALUES ($1, $2, $3, $4) RETURNING id',
    [username, email, role, hash]
  );
  res.json({ id: result.rows[0].id });
});

// Health check - no auth required
app.get('/health', (req, res) => res.json({ status: 'ok' }));

app.listen(3000, () => console.log('Product API listening on :3000'));
